let state={jobs:[],batches:[],candidate_sets:[],settings:{}},files=[],compareSignature='',sourceOptionsSignature='',retakeDefaultsSignature='',candidateSignature='',masterSignature='';
const draft=JSON.parse(localStorage.getItem('ltx-ui-draft')||'{}');
if(!draft.defaultsV2){draft.seed='831913303995591';draft.defaultsV2=true;localStorage.setItem('ltx-ui-draft',JSON.stringify(draft))}
