const fileKey=f=>`${f.name}:${f.size}:${f.lastModified}`;
const libraryFileKey=f=>f._librarySha256?`lib:${f._librarySha256}`:fileKey(f);
const segmentFileKey=f=>libraryFileKey(f);
const uiId=()=>{const webCrypto=globalThis.crypto;if(webCrypto&&typeof webCrypto.randomUUID==='function')return webCrypto.randomUUID();if(webCrypto&&typeof webCrypto.getRandomValues==='function'){const values=new Uint32Array(4);webCrypto.getRandomValues(values);return [...values].map(value=>value.toString(16).padStart(8,'0')).join('-')}return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`};
const asciiKey=value=>{const bytes=new TextEncoder().encode(value);let text='';bytes.forEach(x=>text+=String.fromCharCode(x));return btoa(text)};
const api=async(url,opt={})=>{const key=sessionStorage.getItem('ltx-key')||'';const headers={...(opt.headers||{})};delete headers['x-access-key'];if(key)headers['x-access-key-b64']=asciiKey(key);let r;try{r=await fetch(url,{...opt,headers})}catch(error){throw Error(`UI 서버 요청에 연결하지 못했습니다. 페이지를 새로고침한 뒤 다시 시도하세요. (${error.message||error})`)}if(r.status===401){const entered=prompt('VIDEO UI 접근 키');if(entered!==null&&entered!==''){sessionStorage.setItem('ltx-key',entered);return api(url,opt)}}let b;try{b=await r.json()}catch{throw Error(`서버 응답 오류 (${r.status})`)}if(!r.ok)throw Error(b.error||r.statusText);return b};
const apiBlob=async url=>{const key=sessionStorage.getItem('ltx-key')||'',headers={};if(key)headers['x-access-key-b64']=asciiKey(key);let r;try{r=await fetch(url,{headers})}catch(error){throw Error(`원본 이미지를 불러오지 못했습니다. (${error.message||error})`)}if(r.status===401){const entered=prompt('VIDEO UI 접근 키');if(entered!==null&&entered!==''){sessionStorage.setItem('ltx-key',entered);return apiBlob(url)}}if(!r.ok){let message=`원본 이미지 응답 오류 (${r.status})`;try{message=(await r.json()).error||message}catch{}throw Error(message)}return r.blob()};
