async function askDeletionPassword(message,confirmLabel='삭제 실행'){const dialog=$('#deleteDialog'),input=$('#deletePassword');$('#deleteDialogMessage').textContent=message;$('#deleteDialogConfirm').textContent=confirmLabel;input.value='';dialog.showModal();setTimeout(()=>input.focus(),0);return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'?input.value:null),{once:true}))}
