const compareSavedImageName=(a,b)=>String(a?.original_name||'').localeCompare(String(b?.original_name||''),'ko',{numeric:true,sensitivity:'base'});
const sortedSavedImageLibrary=()=>[...savedImageLibrary].sort(compareSavedImageName);
function goPage(page){const button=document.querySelector(`nav button[data-page="${page}"]`);if(!button)return;currentPage=page;$$('nav button').forEach(x=>x.classList.toggle('active',x===button));$$('[data-view]').forEach(x=>x.hidden=x.dataset.view!==page);$('#title').textContent=pageTitles[page];history.replaceState(null,'','#'+page)}
$$('nav button').forEach(b=>b.onclick=()=>goPage(b.dataset.page));
function renderSegments(){const live=new Map(currentSegments().map(x=>[x.key,x])),saved=new Map((draft.segmentTexts||[]).map(x=>[x.key,x]));let box=$('#segments');box.innerHTML='';files.forEach((f,i)=>{const key=segmentFileKey(f),v=live.get(key)||saved.get(key)||{};let d=document.createElement('div');d.className='segment';d.dataset.key=key;let img=document.createElement('img');img.src=URL.createObjectURL(f);img.alt=f.name;let fields=document.createElement('div');let name=document.createElement('strong');name.textContent=f.name;let prompt=document.createElement('textarea');prompt.className='segment-prompt';prompt.placeholder='이 이미지에서 생성할 장면 프롬프트';prompt.value=v.prompt||'';fields.append(name,prompt);let controls=document.createElement('div');controls.className='segment-controls';controls.innerHTML=`<label>순서<input class="segment-order" type="number" min="1" value="${v.order||i+1}"></label><label>구간(초)<input class="segment-seconds" type="number" min="0.1" step="0.1" value="${v.seconds||5}"></label>`;let remove=document.createElement('button');remove.type='button';remove.className='remove-image';remove.textContent='제거';remove.onclick=()=>{files=files.filter(x=>segmentFileKey(x)!==key);renderSegments();renderSavedImageLibrary();saveDraft()};controls.append(remove);d.append(img,fields,controls);box.append(d)});$('#imageCount').textContent=files.length?`${files.length}개 이미지 선택됨 · 추가 드롭 가능`:'선택된 이미지 없음';box.oninput=saveDraft}
function addFiles(list){const allowed=/\.(png|jpe?g|webp)$/i,known=new Set(files.map(segmentFileKey));for(const f of list){if((f.type.startsWith('image/')||allowed.test(f.name))&&!known.has(segmentFileKey(f))){files.push(f);known.add(segmentFileKey(f))}}renderSegments();renderSavedImageLibrary();saveDraft()}
const formatBytes=value=>{const n=Number(value)||0;if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;return `${(n/(1024*1024)).toFixed(1)} MB`};
async function ensureSavedImageLibrary(force=false){if(!force&&savedImageLibrary.length&&savedImageLibrarySignature)return;const payload=await api('/api/source-images/library');if(!Array.isArray(payload.images))throw Error('저장 이미지 목록 형식이 올바르지 않습니다. UI 서버를 재시작한 뒤 페이지를 새로고침하세요.');savedImageLibrary=payload.images.sort(compareSavedImageName);savedImageLibrarySignature=savedImageLibrary.map(item=>`${item.sha256}:${item.ref_count}`).join('|');if(force)savedImageLibraryVisibleCount=SAVED_IMAGE_PAGE_SIZE}
function selectedLibraryShaSet(){return new Set(files.map(file=>file._librarySha256).filter(Boolean))}
function renderSavedImageLibrary(){const box=$('#savedImageLibrary'),meta=$('#savedImageLibraryMeta'),more=$('#savedImageLibraryMore');if(!box)return;const selected=selectedLibraryShaSet(),sorted=sortedSavedImageLibrary();if(!sorted.length){box.className='saved-image-grid muted';box.textContent='저장된 이미지가 없습니다.';if(meta)meta.textContent='0개';if(more)more.hidden=true;return}if(meta)meta.textContent=`${sorted.length}개 · 이름순`;const visible=sorted.slice(0,savedImageLibraryVisibleCount);box.className='saved-image-grid';box.innerHTML=visible.map(item=>`<button type="button" class="saved-image-card ${selected.has(item.sha256)?'selected':''}" data-saved-image="${esc(item.sha256)}"><img src="${esc(item.preview_url)}" alt="${esc(item.original_name)}" loading="lazy"><b>${esc(item.original_name)}</b><small>${formatBytes(item.size_bytes)} · 참조 ${esc(item.ref_count)} · ${esc(item.latest_job_id)}</small></button>`).join('');$$('[data-saved-image]').forEach(button=>button.onclick=()=>selectSavedImage(button.dataset.savedImage));if(more){const remaining=sorted.length-visible.length;if(remaining>0){more.hidden=false;more.textContent=`더 보기 (${Math.min(remaining,SAVED_IMAGE_PAGE_SIZE)}개)`}else more.hidden=true}}
async function selectSavedImage(sha256){try{const item=savedImageLibrary.find(entry=>entry.sha256===sha256);if(!item)throw Error('저장된 이미지를 찾을 수 없습니다.');if(selectedLibraryShaSet().has(sha256)){note('이미 장면 목록에 추가된 이미지입니다.');return}const blob=await apiBlob(item.preview_url),file=new File([blob],item.original_name,{type:blob.type||'image/png'});file._librarySha256=item.sha256;addFiles([file]);note(`저장 이미지 추가: ${item.original_name}`)}catch(error){note(error.message,true)}}
function renderSourceImagesPage(){const box=$('#sourceImagesGrid'),summary=$('#sourceImagesSummary');if(!box)return;const sorted=sortedSavedImageLibrary();if(!sorted.length){box.className='saved-image-grid muted';box.textContent='저장된 이미지가 없습니다.';if(summary)summary.textContent='고유 이미지 0개';return}const totalRefs=sorted.reduce((sum,item)=>sum+(Number(item.ref_count)||0),0);if(summary)summary.textContent=`고유 이미지 ${sorted.length}개 · 총 참조 ${totalRefs}개 · 이름순`;box.className='saved-image-grid';box.innerHTML=sorted.map(item=>`<div class="saved-image-card manage"><img src="${esc(item.preview_url)}" alt="${esc(item.original_name)}" loading="lazy"><b>${esc(item.original_name)}</b><small>${formatBytes(item.size_bytes)} · 참조 ${esc(item.ref_count)} · 최근 ${esc(item.latest_job_id)}</small><small>${esc(item.sha256.slice(0,12))}…</small><button type="button" class="danger" data-delete-source-image="${esc(item.sha256)}">이미지 삭제</button></div>`).join('');$$('[data-delete-source-image]').forEach(button=>button.onclick=()=>deleteSourceImage(button.dataset.deleteSourceImage))}
async function deleteSourceImage(sha256){const item=savedImageLibrary.find(entry=>entry.sha256===sha256);if(!item)return;if(!confirm(`"${item.original_name}" 이미지를 삭제할까요?\n\n모든 작업 폴더의 동일 파일(${item.ref_count}개 참조)이 제거됩니다. 생성된 영상은 유지됩니다.`))return;try{await api(`/api/source-images/${encodeURIComponent(sha256)}`,{method:'DELETE'});files=files.filter(file=>file._librarySha256!==sha256);savedImageLibrarySignature='';savedImageLibraryVisibleCount=SAVED_IMAGE_PAGE_SIZE;await ensureSavedImageLibrary(true);renderSavedImageLibrary();renderSourceImagesPage();renderSegments();note(`저장 이미지를 삭제했습니다: ${item.original_name}`)}catch(error){note(error.message,true)}}
function createSeedRecommendPayload(){const form=new FormData($('#createForm')),[width,height]=String(form.get('resolution')||'1536x864').split('x').map(Number);return {global_prompt:String(form.get('global_prompt')||''),fps:Number(form.get('fps')||24),width,height,segments:$$('.segment').map(row=>({prompt:row.querySelector('.segment-prompt').value.trim(),order:Number(row.querySelector('.segment-order').value),sha256:files.find(file=>segmentFileKey(file)===row.dataset.key)?._librarySha256||''})).filter(item=>item.prompt)}}
async function ensureSeedLibrary(force=false){if(!force&&seedLibraryLikedJobIds.size)return;const payload=await api('/api/seed-library');seedLibraryLikedJobIds=new Set(Array.isArray(payload.liked_job_ids)?payload.liked_job_ids:[])}
function renderSeedRecommendations(recommendations=[],meta=''){const box=$('#seedRecommendList'),summary=$('#seedRecommendMeta');if(!box)return;if(summary)summary.textContent=meta||'분석 대기';if(!recommendations.length){box.className='seed-recommend-list muted';box.textContent='저장된 seed가 없거나 현재 프롬프트와 유사한 추천이 없습니다.';return}box.className='seed-recommend-list';box.innerHTML=recommendations.map(item=>`<article class="seed-recommend-card"><b>${esc(item.video_noise_seed)}</b><small>score ${esc(item.score)} · ${esc((item.reasons||[]).join(' · ')||'유사도 기준')}</small>${item.matched_tokens?.length?`<small>매칭: ${esc(item.matched_tokens.join(', '))}</small>`:''}<div class="seed-recommend-actions"><button type="button" data-apply-seed="${esc(item.video_noise_seed)}">seed 적용</button><button type="button" data-random-seed="1">다시 랜덤(−1)</button></div></article>`).join('');$$('[data-apply-seed]').forEach(button=>button.onclick=()=>{const input=$('#createForm [name="seed"]');if(input){input.value=button.dataset.applySeed;saveDraft();note(`추천 seed 적용: ${button.dataset.applySeed}`)}scheduleSeedRecommend()});$$('[data-random-seed]').forEach(button=>button.onclick=()=>{const input=$('#createForm [name="seed"]');if(input){input.value='-1';saveDraft();note('비디오 seed를 자동 랜덤(−1)으로 되돌렸습니다.')}scheduleSeedRecommend()})}
function scheduleSeedRecommend(){clearTimeout(seedRecommendTimer);seedRecommendTimer=setTimeout(()=>refreshSeedRecommendations().catch(()=>{}),500)}
async function refreshSeedRecommendations(){const payload=createSeedRecommendPayload(),signature=JSON.stringify(payload);if(signature===seedRecommendSignature)return;seedRecommendSignature=signature;await ensureSeedLibrary();const out=await api('/api/seed-library/recommend',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});renderSeedRecommendations(out.recommendations||[],out.query_token_count?`토큰 ${out.query_token_count}개 · 추천 ${(out.recommendations||[]).length}개`:'추천 없음')}
async function likeCandidateSeed(jobId){try{await api('/api/seed-library/like',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({job_id:jobId})});seedLibraryLikedJobIds.add(jobId);candidateSignature='';renderCandidateSets();note(`seed 저장: ${jobId}`)}catch(error){note(error.message,true)}}
