const zone=$('#uploadZone'),picker=$('#images');$('#chooseImages').onclick=e=>{e.stopPropagation();picker.click()};zone.onclick=e=>{if(e.target===zone||e.target.tagName==='STRONG'||e.target.tagName==='SPAN'||e.target.tagName==='SMALL')picker.click()};zone.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();picker.click()}};picker.onchange=e=>{addFiles(e.target.files);picker.value=''};for(const event of ['dragenter','dragover'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.add('dragging')});for(const event of ['dragleave','drop'])zone.addEventListener(event,e=>{e.preventDefault();zone.classList.remove('dragging')});zone.addEventListener('drop',e=>addFiles(e.dataTransfer.files));
$('#createForm').oninput=()=>{saveDraft();scheduleSeedRecommend()};for(const [k,v] of Object.entries(draft)){let x=$(`#createForm [name="${CSS.escape(k)}"]`);if(x&&typeof v==='string')x.value=v}
$('#createForm').onsubmit=async e=>{e.preventDefault();try{if(!files.length)throw Error('이미지를 한 장 이상 추가하세요.');let form=new FormData(e.target),[width,height]=form.get('resolution').split('x').map(Number),els=$$('.segment'),segments=els.map(x=>{const file=files.find(f=>segmentFileKey(f)===x.dataset.key);return{file,prompt:x.querySelector('.segment-prompt').value.trim(),seconds:+x.querySelector('.segment-seconds').value,order:+x.querySelector('.segment-order').value}});if(segments.some(x=>!x.prompt))throw Error('모든 이미지에 장면 프롬프트를 입력하세요.');let shortLongPrompts=segments.filter(x=>x.prompt.length>=500&&x.seconds<5);if(shortLongPrompts.length&&!confirm(`긴 프롬프트에 비해 구간 시간이 짧습니다.\n\n${shortLongPrompts.map(x=>`순서 ${x.order}: ${x.prompt.length}자 / ${x.seconds}초`).join('\n')}\n\n동작·대사·장면 전환이 불안정할 수 있습니다. 시간을 5초 이상으로 늘리거나, 그대로 등록하세요.`))return;let data={job_name:form.get('job_name'),fps:+form.get('fps'),seed:+form.get('seed'),width,height,global_prompt:form.get('global_prompt'),segments:segments.map(({file,...x})=>x)};let body=new FormData();body.set('data',JSON.stringify(data));segments.forEach((x,i)=>body.set('image_'+i,x.file));let out=await api('/api/jobs',{method:'POST',body});note(`큐 등록: ${out.job_id}`);savedImageLibrarySignature='';await load()}catch(x){note(x.message,true)}};
function buildCandidateRequest(){if(!files.length)throw Error('이미지를 한 장 이상 추가하세요.');const form=new FormData($('#createForm')),[width,height]=String(form.get('resolution')).split('x').map(Number),segments=$$('.segment').map(row=>{const file=files.find(item=>segmentFileKey(item)===row.dataset.key);return{file,prompt:row.querySelector('.segment-prompt').value.trim(),seconds:Number(row.querySelector('.segment-seconds').value),order:Number(row.querySelector('.segment-order').value)}});if(segments.some(item=>!item.prompt))throw Error('모든 이미지에 장면 프롬프트를 입력하세요.');const warnings=segments.filter(item=>item.prompt.length>=500&&item.seconds<5);if(warnings.length&&!confirm(`긴 프롬프트에 비해 구간 시간이 짧습니다.\n\n${warnings.map(item=>`순서 ${item.order}: ${item.prompt.length}자 / ${item.seconds}초`).join('\n')}\n\n후보 영상이 불안정할 수 있습니다. 그대로 후보군을 등록할까요?`))return null;const data={job_name:form.get('job_name'),fps:Number(form.get('fps')),seed:Number(form.get('seed')),width,height,global_prompt:form.get('global_prompt'),candidate_count:Number(form.get('candidate_count')||3),segments:segments.map(({file,...item})=>item)},body=new FormData();body.set('data',JSON.stringify(data));segments.forEach((item,index)=>body.set('image_'+index,item.file));return body}
$('#createCandidates').onclick=async()=>{try{const body=buildCandidateRequest();if(!body)return;if(!confirm('같은 설정에서 서로 다른 비디오 seed로 후보군을 생성 큐에 등록할까요?'))return;const out=await api('/api/candidate-sets',{method:'POST',body});note(`후보군 등록: ${out.candidate_set_id}`);goPage('queue');await load()}catch(error){note(error.message,true)}};


const rootId=j=>j.request.root_job_id||j.job_id;const deletableBatchStatuses=new Set(['completed_generation_only','review_completed','manual_review_required','modification_limit_reached','review_complete_needs_modification','ai_review_failed','failed','cancelled','pipeline_failed','awaiting_candidate_selection','candidate_selected']);
async function deleteBatchHistory(batchId){const deletionPassword=await askDeletionPassword('배치 진행 이력만 삭제합니다. 영상과 결과 작업은 유지됩니다. 삭제 비밀번호를 입력하세요.');if(deletionPassword===null)return;if(!deletionPassword){note('삭제 비밀번호를 입력하세요.',true);return}try{await api(`/api/batches/${encodeURIComponent(batchId)}`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({deletion_password:deletionPassword})});note(`배치 이력을 삭제했습니다: ${batchId}`);await load()}catch(error){note(error.message,true)}}
async function deleteQueuedJob(jobId){const deletionPassword=await askDeletionPassword('아직 실행되지 않은 대기 작업만 큐에서 삭제합니다. 같은 배치의 다른 작업과 완료 파일은 유지됩니다. 삭제 비밀번호를 입력하세요.','대기 작업 삭제');if(deletionPassword===null)return;if(!deletionPassword){note('삭제 비밀번호를 입력하세요.',true);return}try{await api(`/api/jobs/${encodeURIComponent(jobId)}/queue`,{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({deletion_password:deletionPassword})});note(`대기 작업을 삭제했습니다: ${jobId}`);await load()}catch(error){note(error.message,true)}}
async function forceCancelBatch(batchId){const deletionPassword=await askDeletionPassword('이 배치의 실행 중·대기 작업을 취소하고 Worker, ComfyUI, vLLM을 정지합니다. 이미 완료된 결과는 유지됩니다. 강제 종료 비밀번호를 입력하세요.','배치 강제 종료');if(deletionPassword===null)return;if(!deletionPassword){note('강제 종료 비밀번호를 입력하세요.',true);return}try{const out=await api(`/api/batches/${encodeURIComponent(batchId)}/force-cancel`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({deletion_password:deletionPassword})});const warning=(out.warnings||[]).join(' · ');note(warning?`배치를 취소했지만 확인이 필요합니다: ${warning}`:`배치를 강제 종료했습니다: ${batchId}`,Boolean(warning));await load()}catch(error){note(error.message,true)}}

