function assemblyClipDuration(clip){return Math.max(0,Number(clip.end_seconds||0)-Number(clip.start_seconds||0))}
function formatAssemblySeconds(value){const number=Number(value);if(!Number.isFinite(number))return '0';return Number.isInteger(number)?String(number):String(Math.round(number*100)/100)}
function assemblyTimelineInputFocused(){const view=document.querySelector('[data-view="assembly"]');if(!view||view.hidden)return null;const active=document.activeElement;if(!active?.matches('[data-assembly-start],[data-assembly-end]'))return null;return {clipId:active.dataset.assemblyStart||active.dataset.assemblyEnd,field:active.dataset.assemblyStart?'start':'end',value:active.value,selectionStart:active.selectionStart,selectionEnd:active.selectionEnd}}
