 if(summary){summary.className=`assembly-summary ${validation.ok?'ok':'bad'}`;summary.textContent=validation.ok?validation.message:validation.message}
 $('#assemblyTimelineMeta').textContent=`${assemblyTimeline.length} / ${MAX_ASSEMBLY_CLIPS} 클립 · ${assemblyTimelineTotal().toFixed(1)}초`;
