 const remove=event.target.closest('[data-remove-assembly]');if(remove){removeAssemblyClip(remove.dataset.removeAssembly);return}
 const moveUp=event.target.closest('[data-move-up]');if(moveUp){moveAssemblyClip(moveUp.dataset.moveUp,-1);return}
